function canDeal(cards: number[], k: number): boolean {
  if (cards.length % k !== 0) return false;
  const rest = [...cards].sort((a, b) => a - b);
  while (rest.length) {
    const x = rest[0];
    for (let v = x; v < x + k; v++) {
      const at = rest.indexOf(v);
      if (at === -1) return false;
      rest.splice(at, 1);
    }
  }
  return true;
}

