function canDeal(cards: number[], k: number): boolean {
  if (cards.length % k !== 0) return false;
  const count = new Map<number, number>();
  for (const c of cards) count.set(c, (count.get(c) ?? 0) + 1);
  const values = [...count.keys()].sort((a, b) => a - b);
  for (const x of values) {
    const c = count.get(x)!;
    if (c === 0) continue;
    for (let v = x; v < x + k; v++) {
      const have = count.get(v) ?? 0;
      if (have < c) return false;
      count.set(v, have - c);
    }
  }
  return true;
}

